export const SETTINGS_BY_KEY: ReadonlyMap<string, SettingDef> = new Map(
  SETTINGS.map((d) => [d.key, d]),
);

export function settingsForSection(section: SettingSection): SettingDef[] {
  return SETTINGS.filter((d) => d.section === section);
}

export function isSecretSetting(key: string): boolean {
  return SETTINGS_BY_KEY.get(key)?.kind === 'secret';
}

/** Internal keys stored in app_settings that are never shown as editable fields. */
export const INTERNAL_SETTING_KEYS = {
  setupComplete: 'MAS_SETUP_COMPLETE',
  setupCode: 'internal.setup_code',
  lastDiscovery: 'internal.last_discovery',
  lastConnectionTest: 'internal.last_connection_test',
} as const;
